import{_ as p,a0 as d,w as l,s as n,ao as a,I as r,x as t,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何使用 GRUB 2 直接從硬盤運行 ISO 文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 GRUB 2 直接從硬盤運行 ISO 文件 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 GRUB 2 直接從硬盤運行 ISO 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 GRUB 2 直接從硬盤運行 ISO 文件 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150908 How to Run ISO Files Directly From the HDD with GRUB2","title":"如何使用 GRUB 2 直接從硬盤運行 ISO 文件","tag":"201510","desc":""},"relativePath":"201510/20150908 How to Run ISO Files Directly From the HDD with GRUB2.md","filePath":"[post].md"}'),u={name:"201510/20150908 How to Run ISO Files Directly From the HDD with GRUB2.md"};function m(c,e,h,f,w,b){const o=d("Link");return l(),n("div",null,[e[16]||(e[16]=a('<h1 id="如何使用-grub-2-直接從硬盤運行-iso-文件" tabindex="-1">如何使用 GRUB 2 直接從硬盤運行 ISO 文件 <a class="header-anchor" href="#如何使用-grub-2-直接從硬盤運行-iso-文件" aria-label="Permalink to “如何使用 GRUB 2 直接從硬盤運行 ISO 文件”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-featured.png" alt=""></p><p>大多數 Linux 發行版都會提供一個可以從 USB 啓動的 live 環境，以便用户無需安裝即可測試系統。我們可以用它來評測這個發行版或僅僅是當成一個一次性系統，並且很容易將這些文件複製到一個 U 盤上，在某些情況下，我們可能需要經常運行同一個或不同的 ISO 鏡像。GRUB 2 可以配置成直接從啓動菜單運行一個 live 環境，而不需要燒錄這些 ISO 到硬盤或 USB 設備。</p><h3 id="獲取和檢查可啓動的-iso-鏡像" tabindex="-1">獲取和檢查可啓動的 ISO 鏡像 <a class="header-anchor" href="#獲取和檢查可啓動的-iso-鏡像" aria-label="Permalink to “獲取和檢查可啓動的 ISO 鏡像”">​</a></h3><p>為了獲取 ISO 鏡像，我們通常應該訪問所需的發行版的網站下載與我們架構兼容的鏡像文件。如果這個鏡像可以從 U 盤啓動，那它也應該可以從 GRUB 菜單啓動。</p><p>當鏡像下載完後，我們應該通過 MD5 校驗檢查它的完整性。這會輸出一大串數字與字母合成的序列。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-md5.png" alt=""></p><p>將這個序列與下載頁提供的 MD5 校驗碼進行比較，兩者應該完全相同。</p><h3 id="配置-grub-2" tabindex="-1">配置 GRUB 2 <a class="header-anchor" href="#配置-grub-2" aria-label="Permalink to “配置 GRUB 2”">​</a></h3><p>ISO 鏡像文件包含了整個系統。我們要做的僅僅是告訴 GRUB 2 哪裏可以找到 kernel 和 initramdisk 或 initram 文件系統（這取決於我們所使用的發行版）。</p>',10)),r("p",null,[e[1]||(e[1]=t("在下面的例子中，一個 Kubuntu 15.04 live 環境將被配置到 Ubuntu 14.04 機器的 Grub 啓動菜單項。這應該能在大多數新的以 Ubuntu 為基礎的系統上運行。如果你是其它系統並且想實現一些其它的東西，你可以從",-1)),i(o,{href:"http://git.marmotte.net/git/glim/tree/grub2"},{default:s(()=>[...e[0]||(e[0]=[t("這些文件",-1)])]),_:1}),e[2]||(e[2]=t("瞭解更多細節，但這會要求你擁有一點 GRUB 使用經驗。",-1))]),e[17]||(e[17]=a(`<p>這個例子的文件 <code>kubuntu-15.04-desktop-amd64.iso</code> 放在位於 <code>/dev/sda1</code> 的 <code>/home/maketecheasier/TempISOs/</code> 上。</p><p>為了使 GRUB 2 能正確找到它，我們應該編輯</p><pre><code>/etc/grub.d40-custom
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-40-custom-empty.png" alt=""></p><pre><code>menuentry &quot;Kubuntu 15.04 ISO&quot; {
set isofile=&quot;/home/maketecheasier/TempISOs/kubuntu-15.04-desktop-amd64.iso&quot;
loopback loop (hd0,1)$isofile
echo &quot;Starting $isofile...&quot;
linux (loop)/casper/vmlinuz.efi boot=casper iso-scan/filename=\${isofile} quiet splash
initrd (loop)/casper/initrd.lz
}
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-40-custom-new.png" alt=""></p><h3 id="分析上述代碼" tabindex="-1">分析上述代碼 <a class="header-anchor" href="#分析上述代碼" aria-label="Permalink to “分析上述代碼”">​</a></h3><p>首先設置了一個變量名 <code>$menuentry</code> ，這是 ISO 文件的所在位置 。如果你想換一個 ISO ，你應該修改 <code>isofile=&quot;/path/to/file/name-of-iso-file-.iso&quot;</code>.</p><p>下一行是指定迴環設備，且必須給出正確的分區號碼。</p><pre><code>loopback loop (hd0,1)$isofile
</code></pre><p>注意 hd0,1 這裏非常重要，它的意思是第一硬盤，第一分區 (<code>/dev/sda1</code>)。</p><p>GRUB 的命名在這裏稍微有點困惑，對於硬盤來説，它從 “0” 開始計數，第一塊硬盤為 #0 ，第二塊為 #1 ，第三塊為 #2 ，依此類推。但是對於分區來説，它從 “1” 開始計數，第一個分區為 #1 ，第二個分區為 #2 ，依此類推。也許這裏有一個很好的原因，但肯定不是明智的（明顯用户體驗很糟糕）..</p><p>在 Linux 中第一塊硬盤，第一個分區是 <code>/dev/sda1</code> ，但在 GRUB2 中則是 <code>hd0,1</code> 。第二塊硬盤，第三個分區則是 <code>hd1,3</code>, 依此類推.</p><p>下一個重要的行是：</p><pre><code>linux (loop)/casper/vmlinuz.efi boot=casper iso-scan/filename=\${isofile} quiet splash
</code></pre><p>這會載入內核鏡像，在新的 Ubuntu Live CD 中，內核被存放在 <code>/casper</code> 目錄，並且命名為 <code>vmlinuz.efi</code> 。如果你使用的是其它系統，可能會沒有 <code>.efi</code> 擴展名或內核被存放在其它地方 (可以使用歸檔管理器打開 ISO 文件在 <code>/casper</code> 中查找確認)。最後一個選項， <code>quiet splash</code> ，是一個常規的 GRUB 選項，改不改無所謂。</p><p>最後</p><pre><code>initrd (loop)/casper/initrd.lz
</code></pre><p>這會載入 <code>initrd</code> ，它負責載入 RAMDisk 到內存用於啓動。</p><h3 id="啓動-live-系統" tabindex="-1">啓動 live 系統 <a class="header-anchor" href="#啓動-live-系統" aria-label="Permalink to “啓動 live 系統”">​</a></h3><p>做完上面所有的步驟後，需要更新 GRUB2：</p><pre><code>sudo update-grub
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-updare-grub.png" alt=""></p><p>當重啓系統後，應該可以看見一個新的、並且允許我們啓動剛剛配置的 ISO 鏡像的 GRUB 條目：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-grub-menu.png" alt=""></p><p>選擇這個新條目就允許我們像從 DVD 或 U 盤中啓動一個 live 環境一樣。</p><hr>`,27)),r("p",null,[e[4]||(e[4]=t("via: ",-1)),i(o,{href:"https://www.maketecheasier.com/run-iso-files-hdd-grub2/"},{default:s(()=>[...e[3]||(e[3]=[t("https://www.maketecheasier.com/run-iso-files-hdd-grub2/",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=t("作者：",-1)),i(o,{href:"https://www.maketecheasier.com/author/attilaorosz/"},{default:s(()=>[...e[5]||(e[5]=[t("Attila Orosz",-1)])]),_:1}),e[9]||(e[9]=t(" 譯者：",-1)),i(o,{href:"https://github.com/locez"},{default:s(()=>[...e[6]||(e[6]=[t("Locez",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:s(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[13]||(e[13]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const U=p(u,[["render",m]]);export{T as __pageData,U as default};
